"use strict";const FAVORITES_STORAGE_KEY="douaaGeneratorFavorites",elements={grid:document.getElementById("favoritesGrid"),empty:document.getElementById("favoritesEmpty"),error:document.getElementById("favoritesError"),count:document.getElementById("favoritesCount"),clearButton:document.getElementById("clearFavoritesBtn")};async function initializeFavorites(){elements.clearButton.addEventListener("click",clearFavorites);try{const e=await fetch("../data/duas.json?v=26",{cache:"default"});if(!e.ok)throw new Error(`Erreur HTTP ${e.status}`);renderFavorites((await e.json()).duas||[])}catch(e){console.error("Chargement des favoris impossible :",e),elements.count.textContent="Indisponible",elements.error.classList.remove("hidden")}}function readFavorites(){try{const e=JSON.parse(localStorage.getItem(FAVORITES_STORAGE_KEY)||"[]");return Array.isArray(e)?e:[]}catch(e){return console.warn("Favoris illisibles :",e),[]}}function renderFavorites(e){const t=readFavorites(),n=new Map(e.map(e=>[e.id,e])),a=t.map(e=>{const t="string"==typeof e?{id:e}:e,a=n.get(t.id);return a?{dua:a,url:t.url||`../douaa.html?id=${encodeURIComponent(t.id)}`}:null}).filter(Boolean);elements.count.textContent=`${a.length} ${a.length>1?"favoris":"favori"}`,elements.grid.classList.toggle("hidden",0===a.length),elements.empty.classList.toggle("hidden",0!==a.length),elements.clearButton.classList.toggle("hidden",0===a.length),elements.grid.innerHTML=a.map(({dua:e,url:t})=>`\n    <a class="favorite-dua-card" href="${escapeHtml(t)}">\n      <span class="related-dua-type">${escapeHtml(e.type||"Invocation")}</span>\n      <strong>${escapeHtml(e.title||"Douaa")}</strong>\n      <span>${escapeHtml(e.french||"")}</span>\n      <small>${escapeHtml(e.source||"")}</small>\n    </a>\n  `).join("")}function clearFavorites(){window.confirm("Effacer toutes les douaas enregistrées dans vos favoris ?")&&(window.trackEvent?.("clear_favorites",{favorite_count:readFavorites().length}),localStorage.removeItem(FAVORITES_STORAGE_KEY),window.location.reload())}function escapeHtml(e){return String(e??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}document.addEventListener("DOMContentLoaded",initializeFavorites);
